-- ContosoBikesDW: the Contoso Bikes star schema of episode 1, as a SQL Server database (generated by tools/make_sql.py, do not edit).
-- Optional: copies every order line 499 times (new order numbers with a -0001 .. -0499 suffix) so DirectQuery has something to chew on.
-- Totals become exactly 500 times the original ones; the aggregation view still returns the same number of rows.
USE [ContosoBikesDW];
GO
SET NOCOUNT ON;
DECLARE @copies int = 499;   -- 4071 x (1 + 499) order lines
IF EXISTS (SELECT 1 FROM dbo.FactSales WHERE OrderNumber LIKE '%-%')
    THROW 50000, 'FactSales is already scaled up (order numbers with a copy suffix exist). Run 01 and 02 again to start over.', 1;

;WITH n AS (
    SELECT TOP (@copies) ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS CopyNo
    FROM sys.all_objects AS a CROSS JOIN sys.all_objects AS b
)
INSERT INTO dbo.FactSales (OrderNumber, LineNumber, OrderDate, ShipDate, CustomerKey, ProductKey, StoreKey, Quantity, UnitPrice, UnitCost)
SELECT f.OrderNumber + '-' + RIGHT('0000' + CAST(n.CopyNo AS varchar(4)), 4),
       f.LineNumber, f.OrderDate, f.ShipDate, f.CustomerKey, f.ProductKey, f.StoreKey, f.Quantity, f.UnitPrice, f.UnitCost
FROM dbo.FactSales AS f CROSS JOIN n;

SELECT COUNT_BIG(*) AS OrderLines, SUM(LineAmount) AS SalesAmount FROM dbo.FactSales;
GO
